KLEI3_PTR         = C_NULL_PTR ; IF (PRESENT(KLEI3))         KLEI3_PTR         = C_LOC(ILEI3)
KSPOLEGL_PTR      = C_NULL_PTR ; IF (PRESENT(KSPOLEGL))      KSPOLEGL_PTR      = C_LOC(ISPOLEGL)
KSMAX_PTR         = C_NULL_PTR ; IF (PRESENT(KSMAX))         KSMAX_PTR         = C_LOC(ISMAX)
KDEF_RESOL_PTR    = C_NULL_PTR ; IF (PRESENT(KDEF_RESOL))    KDEF_RESOL_PTR    = C_LOC(IDEF_RESOL)
KLAM_PTR          = C_NULL_PTR ; IF (PRESENT(LDLAM))         KLAM_PTR          = C_LOC(ILAM)

IF (PRESENT(LDSPLITLAT)) ALLOCATE(ISPLITLAT(SIZE(LDSPLITLAT)))

#ifdef TRANS_SINGLE
CALL TRANS_INQ_CPP_BINDING_SP(ARGS, KRESOL_PTR, KSPEC_PTR, KSPEC2_PTR, KSPEC2G_PTR, KSPEC2MX_PTR, &
  &  KNUMP_PTR, KGPTOT_PTR, KGPTOTG_PTR, KGPTOTMX_PTR, KFRSTLOFF_PTR, KPTRFLOFF_PTR, KPRTRW_PTR, &
  &  KMYSETW_PTR, KMYSETV_PTR, KMY_REGION_NS_PTR, KMY_REGION_EW_PTR, KLEI3_PTR, KSPOLEGL_PTR, &
  &  KSMAX_PTR, KDEF_RESOL_PTR, KLAM_PTR, KGPTOTL=KGPTOTL, KMYMS=KMYMS, KASM0=KASM0, KUMPP=KUMPP, &
  &  KPOSSP=KPOSSP, KPTRMS=KPTRMS, KALLMS=KALLMS, KDIM0G=KDIM0G, KFRSTLAT=KFRSTLAT, &
  &  KLSTLAT=KLSTLAT, KPTRLAT=KPTRLAT, KPTRFRSTLAT=KPTRFRSTLAT, KPTRLSTLAT=KPTRLSTLAT, KSTA=KSTA, &
  &  KONL=KONL, KULTPP=KULTPP, KPTRLS=KPTRLS, KNMENG=KNMENG, KSPLITLAT=ISPLITLAT, PLAPIN=PLAPIN, &
  &  KNVALUE=KNVALUE, PMU=PMU, PGW=PGW, PRPNM=PRPNM, KPMS=KPMS, KDGLU=KDGLU)
#else
CALL TRANS_INQ_CPP_BINDING_DP(ARGS, KRESOL_PTR, KSPEC_PTR, KSPEC2_PTR, KSPEC2G_PTR, KSPEC2MX_PTR, &
  &  KNUMP_PTR, KGPTOT_PTR, KGPTOTG_PTR, KGPTOTMX_PTR, KFRSTLOFF_PTR, KPTRFLOFF_PTR, KPRTRW_PTR, &
  &  KMYSETW_PTR, KMYSETV_PTR, KMY_REGION_NS_PTR, KMY_REGION_EW_PTR, KLEI3_PTR, KSPOLEGL_PTR, &
  &  KSMAX_PTR, KDEF_RESOL_PTR, KLAM_PTR, KGPTOTL=KGPTOTL, KMYMS=KMYMS, KASM0=KASM0, KUMPP=KUMPP, &
  &  KPOSSP=KPOSSP, KPTRMS=KPTRMS, KALLMS=KALLMS, KDIM0G=KDIM0G, KFRSTLAT=KFRSTLAT, &
  &  KLSTLAT=KLSTLAT, KPTRLAT=KPTRLAT, KPTRFRSTLAT=KPTRFRSTLAT, KPTRLSTLAT=KPTRLSTLAT, KSTA=KSTA, &
  &  KONL=KONL, KULTPP=KULTPP, KPTRLS=KPTRLS, KNMENG=KNMENG, KSPLITLAT=ISPLITLAT, PLAPIN=PLAPIN, &
  &  KNVALUE=KNVALUE, PMU=PMU, PGW=PGW, PRPNM=PRPNM, KPMS=KPMS, KDGLU=KDGLU)
#endif

! --- Copy back the scalar outputs -----------------------------------------------------------------
IF (PRESENT(KSPEC))         KSPEC         = ISPEC
IF (PRESENT(KSPEC2))        KSPEC2        = ISPEC2
IF (PRESENT(KSPEC2G))       KSPEC2G       = ISPEC2G
IF (PRESENT(KSPEC2MX))      KSPEC2MX      = ISPEC2MX
IF (PRESENT(KNUMP))         KNUMP         = INUMP
IF (PRESENT(KGPTOT))        KGPTOT        = IGPTOT
IF (PRESENT(KGPTOTG))       KGPTOTG       = IGPTOTG
IF (PRESENT(KGPTOTMX))      KGPTOTMX      = IGPTOTMX
IF (PRESENT(KFRSTLOFF))     KFRSTLOFF     = IFRSTLOFF
IF (PRESENT(KPTRFLOFF))     KPTRFLOFF     = IPTRFLOFF
IF (PRESENT(KPRTRW))        KPRTRW        = IPRTRW
IF (PRESENT(KMYSETW))       KMYSETW       = IMYSETW
IF (PRESENT(KMYSETV))       KMYSETV       = IMYSETV
IF (PRESENT(KMY_REGION_NS)) KMY_REGION_NS = IMY_REGION_NS
IF (PRESENT(KMY_REGION_EW)) KMY_REGION_EW = IMY_REGION_EW
IF (PRESENT(KLEI3))         KLEI3         = ILEI3
IF (PRESENT(KSPOLEGL))      KSPOLEGL      = ISPOLEGL
IF (PRESENT(KSMAX))         KSMAX         = ISMAX
IF (PRESENT(KDEF_RESOL))    KDEF_RESOL    = IDEF_RESOL
IF (PRESENT(LDLAM))         LDLAM         = ILAM
IF (PRESENT(LDSPLITLAT))    LDSPLITLAT    = ISPLITLAT

END SUBROUTINE TRANS_INQ
